<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\OAuth\Profile\Infrastructure\Driver\Html\Panels;

use Civi\Lughauth\Features\OAuth\WebAuthn\Domain\WebAuthnCredential;

class PasskeysPanel
{
    private const string PASSKEY_SVG = '<svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24"'
        . ' fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">'
        . '<path d="M12 10a2 2 0 0 0-2 2c0 1.02-.1 2.51-.26 4"/>'
        . '<path d="M14 13.12c0 2.38 0 6.38-1 8.88"/>'
        . '<path d="M17.29 21.02c.12-.6.43-2.3.5-3.02"/>'
        . '<path d="M2 12a10 10 0 0 1 18-6"/>'
        . '<path d="M2 17.5a14.5 14.5 0 0 0 4.28 5.5"/>'
        . '<path d="M6 10a6 6 0 0 1 11.29-2.97"/>'
        . '</svg>';

    /**
     * @param WebAuthnCredential[] $credentials
     */
    public function render(
        array $credentials,
        string $renameBaseUrl,
        string $deleteBaseUrl,
        string $cancelUrl,
        ?string $error,
        array $t = [],
    ): string {
        $title = '<h1>' . ($t['title'] ?? 'Passkeys') . '</h1>';
        $help = '<p>' . ($t['help'] ?? '') . '</p>';
        $errorHtml = $error !== null && $error !== ''
            ? '<p class="error">' . htmlspecialchars($error) . '</p>'
            : '';

        $cards = '';
        foreach ($credentials as $cred) {
            $name = htmlspecialchars($cred->deviceName !== null && $cred->deviceName !== ''
                ? $cred->deviceName
                : ($t['unnamed'] ?? 'Unnamed device'));
            $created = htmlspecialchars($cred->createdAt->format('Y-m-d'));
            $lastUsed = htmlspecialchars($cred->lastUsedAt !== null
                ? $cred->lastUsedAt->format('Y-m-d')
                : ($t['never'] ?? 'Never'));
            $uid = htmlspecialchars($cred->uid);
            $deleteUrl = htmlspecialchars($deleteBaseUrl . '/' . $uid . '/delete');
            $renameUrl = htmlspecialchars($renameBaseUrl . '/' . $uid . '/rename');
            $deleteLabel = htmlspecialchars($t['delete'] ?? 'Delete');
            $deleteConfirm = htmlspecialchars($t['deleteConfirm'] ?? 'Delete this passkey?');
            $renameLabel = htmlspecialchars($t['rename'] ?? 'Rename');
            $createdLabel = htmlspecialchars($t['createdAt'] ?? 'Added');
            $lastUsedLabel = htmlspecialchars($t['lastUsed'] ?? 'Last used');
            $currentName = htmlspecialchars($cred->deviceName ?? '');
            $namePlaceholder = htmlspecialchars($t['name'] ?? 'Device name');

            $cards .= <<<HTML
                <div class="passkey-card">
                    <div class="passkey-card-top">
                        <div class="passkey-icon">{$this->passkeyIcon()}</div>
                        <div class="passkey-info">
                            <div class="passkey-name">{$name}</div>
                            <div class="passkey-dates">
                                <span>{$createdLabel}: {$created}</span>
                                <span>{$lastUsedLabel}: {$lastUsed}</span>
                            </div>
                        </div>
                        <div class="passkey-actions">
                            <form method="POST" action="{$deleteUrl}" style="display:inline">
                                <input class="link-button" type="submit" value="{$deleteLabel}"
                                    onclick="return confirm('{$deleteConfirm}')" />
                            </form>
                        </div>
                    </div>
                    <form method="POST" action="{$renameUrl}" class="passkey-rename-form">
                        <input type="text" name="name" value="{$currentName}" placeholder="{$namePlaceholder}" required />
                        <input type="submit" value="{$renameLabel}" />
                    </form>
                </div>
                HTML;
        }

        if ($cards === '') {
            $cards = '<p>' . ($t['empty'] ?? 'No passkeys registered.') . '</p>';
        }

        $backLabel = htmlspecialchars($t['backToProfile'] ?? 'Back to profile');
        $cancelUrl = htmlspecialchars($cancelUrl);

        return $title . $help . $errorHtml . $cards
            . '<div class="profile-actions"><a class="secondary-button" href="' . $cancelUrl . '">'
            . $backLabel . '</a></div>';
    }

    private function passkeyIcon(): string
    {
        return self::PASSKEY_SVG;
    }
}
